const q = ($json.query && $json.query.q) ? String($json.query.q) : '';
const safeQuery = "'" + q.replace(/'/g, "'\\''") + "'";
return [{ json: { query: q, safeQuery, hasQuery: q.trim().length > 0 } }];

function escapeHtml(s) {
  return String(s).replace(/[&<>"']/g, (c) => ({
    '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;', "'": '&#39;'
  }[c]));
}

const query = $('Prepare Query').item.json.query || '';
const hasQuery = $('Has Query?').item.json.hasQuery;

let results = [];
let errorMsg = '';
if (hasQuery) {
  const stdout = $json.stdout || '[]';
  try {
    results = JSON.parse(stdout);
  } catch (e) {
    errorMsg = 'Search failed - no results parsed. Raw output: ' + escapeHtml(stdout).slice(0, 500);
  }
}

const cards = results.map((r) => `
  <figure>
    <img src="${r.url}" loading="lazy" alt="">
    <figcaption>score ${r.score}</figcaption>
  </figure>`).join('');

const statusLine = !hasQuery
  ? ''
  : errorMsg
    ? `<p class="error">${errorMsg}</p>`
    : results.length === 0
      ? '<p>No matches.</p>'
      : `<p>${results.length} matches for "${escapeHtml(query)}"</p>`;

const html = `<!doctype html>
<html>
<head>
<meta charset="utf-8">
<meta name="viewport" content="width=device-width, initial-scale=1">
<title>VaultPi Photo Search</title>
<style>
  body { font-family: system-ui, sans-serif; background: #111; color: #eee; margin: 0; padding: 1rem; }
  form { display: flex; gap: 0.5rem; margin-bottom: 1rem; }
  input[type=text] { flex: 1; padding: 0.6rem; font-size: 1rem; border-radius: 6px; border: 1px solid #444; background: #222; color: #eee; }
  button { padding: 0.6rem 1rem; font-size: 1rem; border-radius: 6px; border: none; background: #4a7; color: #111; }
  .grid { display: grid; grid-template-columns: repeat(auto-fill, minmax(150px, 1fr)); gap: 0.75rem; }
  figure { margin: 0; background: #1a1a1a; border-radius: 8px; overflow: hidden; }
  figure img { width: 100%; height: 150px; object-fit: cover; display: block; }
  figcaption { font-size: 0.75rem; color: #aaa; padding: 0.25rem 0.5rem; }
  .error { color: #f66; }
</style>
</head>
<body>
  <form method="GET">
    <input type="text" name="q" placeholder="search photos..." value="${escapeHtml(query)}">
    <button type="submit">Search</button>
  </form>
  ${statusLine}
  <div class="grid">${cards}</div>
</body>
</html>`;

return [{ json: { html } }];
